import{_ as t,o as e,c as n,a5 as i}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"技術的負債・コードの臭い・リファクタリング","description":"","frontmatter":{"title":"技術的負債・コードの臭い・リファクタリング","study":{"source":"C++ Wiki","status":"published","summary":"技術的負債(technical debt): 「今すぐ動かす」ために「後で直すコスト」を借金すること。借金自体は戦略であり、問題は無自覚な借金と未返済の利息。 コードの臭い(code smell): バグではないが、設計上の問題を示唆する兆候。","section":"reference","format":"article","domain":"design"}},"headers":[],"relativePath":"design/foundations/tech-debt-and-refactoring.md","filePath":"design/foundations/tech-debt-and-refactoring.md"}'),l={name:"design/foundations/tech-debt-and-refactoring.md"};function s(r,a,d,o,h,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="技術的負債・コードの臭い・リファクタリング" tabindex="-1">技術的負債・コードの臭い・リファクタリング <a class="header-anchor" href="#技術的負債・コードの臭い・リファクタリング" aria-label="Permalink to &quot;技術的負債・コードの臭い・リファクタリング&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><ul><li><strong>技術的負債(technical debt)</strong>: 「今すぐ動かす」ために「後で直すコスト」を借金すること。借金自体は戦略であり、問題は<strong>無自覚な借金と未返済の利息</strong>。</li><li><strong>コードの臭い(code smell)</strong>: バグではないが、設計上の問題を示唆する兆候。</li><li><strong>リファクタリング(refactoring)</strong>: <strong>外から見た振る舞いを変えずに</strong>、内部構造を改善すること。</li></ul><h2 id="解決したい問題" tabindex="-1">解決したい問題 <a class="header-anchor" href="#解決したい問題" aria-label="Permalink to &quot;解決したい問題&quot;">​</a></h2><p>締切のあるゲーム開発では「正しい設計を待ってからリリース」はできません。負債という概念は、<strong>意図的に品質を落とす判断を、管理可能な形にする</strong>ためにあります。</p><h2 id="技術的負債" tabindex="-1">技術的負債 <a class="header-anchor" href="#技術的負債" aria-label="Permalink to &quot;技術的負債&quot;">​</a></h2><h3 id="借金のメタファーとその限界" tabindex="-1">借金のメタファーとその限界 <a class="header-anchor" href="#借金のメタファーとその限界" aria-label="Permalink to &quot;借金のメタファーとその限界&quot;">​</a></h3><ul><li>元本 = 雑に書いた部分。利息 = その部分を触るたびに余計にかかる時間。</li><li>良い借金: イベント締切前のハードコード(「イベント終了後に消す」と決まっている)。</li><li>悪い借金: 無自覚な借金。返す予定のない借金が中核システムに積もった状態。</li><li><strong>メタファーの限界</strong>: 金の借金と違い、技術的負債は「触らないコード」なら利息ゼロです。全負債の返済は目標になりません。<strong>よく触る場所の負債だけが高利息</strong>です。</li></ul><h3 id="実務的な管理" tabindex="-1">実務的な管理 <a class="header-anchor" href="#実務的な管理" aria-label="Permalink to &quot;実務的な管理&quot;">​</a></h3><ul><li>借りるときに記録する(コメント <code>// HACK(期限/理由):</code> やタスク票)。</li><li>返済判断は「利息」で決める: そのコードを月に何回触り、毎回何分余計にかかっているか。</li></ul><h2 id="コードの臭い-ゲーム開発でよく出るもの" tabindex="-1">コードの臭い(ゲーム開発でよく出るもの) <a class="header-anchor" href="#コードの臭い-ゲーム開発でよく出るもの" aria-label="Permalink to &quot;コードの臭い(ゲーム開発でよく出るもの)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>臭い</th><th>兆候</th><th>疑うべき問題</th><th>対応する道具</th></tr></thead><tbody><tr><td>神クラス</td><td>GameManager が3000行</td><td><a href="/study/design/foundations/cohesion-and-coupling.html">低凝集</a></td><td>責務ごとに分割</td></tr><tr><td>ショットガン手術</td><td>敵1体追加で7ファイル修正</td><td>知識が散乱(<a href="/study/design/foundations/yagni-kiss-dry.html">DRY</a>違反)</td><td>知識の一元化、<a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a></td></tr><tr><td>増え続けるswitch</td><td>同じ型分岐が複数関数に</td><td><a href="/study/design/solid/ocp.html">OCP</a>の出番</td><td><a href="/study/design/foundations/polymorphism-interface.html">ポリモーフィズム</a></td></tr><tr><td>長すぎる引数リスト</td><td>引数8個の関数</td><td>データのまとまりの見落とし</td><td>構造体にまとめる</td></tr><tr><td>羨望するメソッド</td><td>他クラスのgetterを大量に呼ぶ</td><td>処理の置き場所が違う</td><td>処理をデータ側へ移す</td></tr><tr><td>フラグの増殖</td><td><code>isDying &amp;&amp; !isDead &amp;&amp; isStunned</code></td><td>状態設計の欠如</td><td><a href="/study/design/patterns/state.html">State</a> / <a href="/study/game/patterns/state-machines.html">FSM</a></td></tr><tr><td>コメントだらけ</td><td>説明しないと読めないコード</td><td>名前と構造の失敗</td><td>抽出と改名</td></tr></tbody></table><p>臭いは<strong>兆候であって判決ではない</strong>。神クラスでも、変更が来ないなら放置が正解のこともあります。</p><h2 id="リファクタリング" tabindex="-1">リファクタリング <a class="header-anchor" href="#リファクタリング" aria-label="Permalink to &quot;リファクタリング&quot;">​</a></h2><h3 id="定義の厳密な意味" tabindex="-1">定義の厳密な意味 <a class="header-anchor" href="#定義の厳密な意味" aria-label="Permalink to &quot;定義の厳密な意味&quot;">​</a></h3><p>「振る舞いを変えずに」が肝です。<strong>機能追加とリファクタリングを同時にやらない</strong>。混ぜると、バグったとき原因が構造変更か機能変更か分からなくなります。</p><ol><li>まず現状の振る舞いを固定する(テスト、なければ手動確認手順)</li><li>小さい構造変更を1つ行い、振る舞いが変わっていないことを確認</li><li>繰り返す。機能追加は構造が整ってから別コミットで</li></ol><h3 id="問題のある進め方-→-改善した進め方" tabindex="-1">問題のある進め方 → 改善した進め方 <a class="header-anchor" href="#問題のある進め方-→-改善した進め方" aria-label="Permalink to &quot;問題のある進め方 → 改善した進め方&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>悪い: 「汚いので全面書き直し」— 3週間ゲームがビルドできない。</span></span>
<span class="line"><span>      仕様の暗黙知(あのif文は実は不具合回避だった)を失って劣化する。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>良い: 動かしたまま少しずつ。</span></span>
<span class="line"><span>      例: 神クラスGameManagerの解体</span></span>
<span class="line"><span>      1. スコア関連の関数と変数を洗い出す(変更なし)</span></span>
<span class="line"><span>      2. ScoreBoardクラスへ移し、GameManagerは委譲で旧APIを維持</span></span>
<span class="line"><span>      3. 呼び出し側を段階的に新APIへ</span></span>
<span class="line"><span>      4. 旧APIを削除</span></span>
<span class="line"><span>      各段階でゲームは常に動く。</span></span></code></pre></div><h3 id="いつやるか" tabindex="-1">いつやるか <a class="header-anchor" href="#いつやるか" aria-label="Permalink to &quot;いつやるか&quot;">​</a></h3><ul><li><strong>やる</strong>: これから機能追加する場所が汚いとき(「触るついで」が最有効。準備のリファクタリング)。バグの温床になっている場所。</li><li><strong>やらない</strong>: 触る予定のない場所。リリース直前。振る舞いを固定する手段が何もないとき(先に確認手段を作る)。</li><li>詳細な判断フロー: <a href="/study/design/decisions/optimize-or-refactor.html">判断ガイド: リファクタリングすべきか</a></li></ul><h2 id="何が改善され、何を失うか" tabindex="-1">何が改善され、何を失うか <a class="header-anchor" href="#何が改善され、何を失うか" aria-label="Permalink to &quot;何が改善され、何を失うか&quot;">​</a></h2><ul><li>改善: 変更コストの低下、バグ混入率の低下、知識の整理。</li><li>失うもの: 直接の機能進捗ゼロの時間。リグレッションのリスク。チームメンバーの「あのコードどこ行った」コスト。<strong>リファクタリングは常に善ではなく、投資判断</strong>です。</li></ul><h2 id="ゲーム開発での例" tabindex="-1">ゲーム開発での例 <a class="header-anchor" href="#ゲーム開発での例" aria-label="Permalink to &quot;ゲーム開発での例&quot;">​</a></h2><ul><li>プロトタイプ→製品化の境目が最大の返済ポイント。「プロトタイプのコードを本番に育てる」なら、この時点で中核(ゲームループ、データフロー)だけは返済する。</li><li>ライブ運用中のタイトルは「動いているものを触るリスク」が高いので、返済は機能追加と抱き合わせで少しずつが定石。</li></ul><h2 id="unity-c-との対応" tabindex="-1">Unity/C# との対応 <a class="header-anchor" href="#unity-c-との対応" aria-label="Permalink to &quot;Unity/C# との対応&quot;">​</a></h2><ul><li>「Prefab直しも同時にやる」はリファクタリングの原則違反になりがち(振る舞い固定が崩れる)。コードとアセットの変更は分ける。</li><li>IDEのリネーム・メソッド抽出は振る舞い保存が保証された安全な操作。ただしUnityのSerializeFieldやAnimationEventの文字列参照はIDEが追えないので注意。</li></ul><h2 id="unreal-engine-との対応" tabindex="-1">Unreal Engine との対応 <a class="header-anchor" href="#unreal-engine-との対応" aria-label="Permalink to &quot;Unreal Engine との対応&quot;">​</a></h2><ul><li>BlueprintからのC++関数参照も文字列的な結合(リダイレクタで緩和)。C++側のリネームはCore Redirects の設定とセットで行います。</li></ul><h2 id="よくある誤解" tabindex="-1">よくある誤解 <a class="header-anchor" href="#よくある誤解" aria-label="Permalink to &quot;よくある誤解&quot;">​</a></h2><ul><li>「リファクタリング = 書き直し」ではありません。全面書き直しはリファクタリングの対極にある最高リスクの手段です。</li><li>「負債ゼロを目指すべき」でもありません。締切のある開発で負債ゼロは「借金を恐れて家を買わない」のと同じで、機会損失です。</li></ul><h2 id="使う場面-使わない場面" tabindex="-1">使う場面 / 使わない場面 <a class="header-anchor" href="#使う場面-使わない場面" aria-label="Permalink to &quot;使う場面 / 使わない場面&quot;">​</a></h2><ul><li><strong>負債を意図的に借りる場面</strong>: 検証したい仮説がある(面白いか分からない機能)、締切、イベント限定コード。</li><li><strong>借りない場面</strong>: セーブデータ形式・通信プロトコルなど返済不能になりやすい場所。</li></ul><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI・KISS・DRY</a></li><li><a href="/study/design/foundations/quality-attributes.html">設計の品質特性</a></li><li><a href="/study/design/decisions/optimize-or-refactor.html">判断ガイド: 最適化すべきか・リファクタリングすべきか</a></li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>技術的負債の「利息」とは具体的に何ですか。利息が高い負債はどんな場所にありますか。</li><li>リファクタリングと機能追加を混ぜてはいけない理由は?</li><li>コードの臭いが「判決ではない」とはどういう意味ですか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のプロジェクトで最も触る頻度の高いファイルを1つ選び、上の臭い表と照合してください。臭いが見つかったら、「動かしたまま1段階だけ」の改善手順(5ステップ以内)を書いてください。実施は任意です。</p><hr><p>関連項目：<a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI・KISS・DRY</a> / <a href="/study/design/foundations/">学習ガイド</a> / <a href="/study/design/foundations/exercises.html">演習</a></p>`,41)])])}const g=t(l,[["render",s]]);export{p as __pageData,g as default};
